async _makeRequest(path, details = {}) {
  const serverURI = Services.io.newURI(this._serverURL);
  if (!this._isOnServer(path)) {
    throw Components.Exception(
      `Refusing to send a request for ${path} to a different server than ${serverURI.prePath}`,
      Cr.NS_ERROR_ABORT
    );
  }
  const uri = serverURI.resolve(path);
  const username = this.getStringValue("carddav.username", "");

  const callbacks = new lazy.NotificationCallbacks(username);
  details.callbacks = callbacks;

  details.userContextId =
    this._userContextId ?? lazy.CardDAVUtils.contextForUsername(username);

  let response;
  try {
    // Notify before resolving authentication. That reads from the login
    // manager, which can take a while, and the directory is already busy.
    Services.obs.notifyObservers(
      this,
      "addrbook-directory-request-start",
      this.UID
    );

    if (!("_oAuth" in this)) {
      for (const login of await Services.logins.searchLoginsAsync({
        origin: serverURI.prePath,
      })) {
        // If we have a saved login, it might be a Fastmail user with an app password,
        // in which case we want to use it for authentication instead of OAuth2.
        if (login.username == username) {
          this._oAuth = null; // Use this saved login instead of OAuth.
          break;
        }
      }
    }
    if (!("_oAuth" in this)) {
      const oAuth = new lazy.OAuth2Module();
      if (
        oAuth.initFromHostname(
          serverURI.host,
          username || this.UID,
          "carddav"
        )
      ) {
        this._oAuth = oAuth;
      } else {
        this._oAuth = null; // Prevents this block from running again.
      }
    }
    details.oAuth = this._oAuth;

    response = await lazy.CardDAVUtils.makeRequest(uri, details);
  } finally {
    Services.obs.notifyObservers(
      this,
      "addrbook-directory-request-end",
      this.UID
    );
  }
  if (
    details.expectedStatuses &&
    !details.expectedStatuses.includes(response.status)
  ) {
    throw Components.Exception(
      `Incorrect response from server: ${response.status} ${response.statusText}`,
      Cr.NS_ERROR_FAILURE
    );
  }

  if (callbacks.shouldSaveAuth) {
    // The user was prompted for a username and password. Save the response.
    this.setStringValue("carddav.username", callbacks.authInfo?.username);
    await callbacks.saveAuth();
  }
  return response;
